    about_story_sub: "ਅਸੀਂ ਕਿਵੇਂ ਸ਼ੁਰੂ ਕੀਤਾ ਅਤੇ ਕਿੱਥੇ ਜਾ ਰਹੇ ਹਾਂ।",
    story_beginning_title: "ਸ਼ੁਰੂਆਤ",
    story_beginning_p1: "2022 ਵਿੱਚ ਰੀਅਲ ਅਸਟੇਟ ਅਤੇ ਫਿਨਟੈਕ ਮਾਹਰਾਂ ਦੀ ਟੀਮ ਦੁਆਰਾ ਸਥਾਪਿਤ, ਜ਼ਾਰੋਨ ਇੱਕ ਸਧਾਰਨ ਨਿਰੀਖਣ ਤੋਂ ਜਨਮਿਆ: ਸਾਊਦੀ ਅਰਬ ਦੀ ਵਧਦੀ ਰੀਅਲ ਅਸਟੇਟ ਮਾਰਕੀਟ ਸਿਰਫ਼ ਅਮੀਰ ਵਰਗ ਲਈ ਪਹੁੰਚਯੋਗ ਸੀ।",
    story_beginning_p2: "ਅਸੀਂ ਇਸ ਪਹੁੰਚ ਨੂੰ ਸਾਰਿਆਂ ਲਈ ਖੋਲ੍ਹਣ ਅਤੇ ਵਿਜ਼ਨ 2030 ਦੇ ਆਰਥਿਕ ਵਿਭਿੰਨਤਾ ਅਤੇ ਆਮ ਨਿਵੇਸ਼ ਭਾਗੀਦਾਰੀ ਵਧਾਉਣ ਦੇ ਟੀਚਿਆਂ ਨਾਲ ਜੋੜਨ ਦਾ ਮੌਕਾ ਵੇਖਿਆ।",
    story_founded_label: "ਜ਼ਾਰੋਨ ਦੀ ਸਥਾਪਨਾ",
    story_launch_title: "ਪਲੇਟਫਾਰਮ ਲਾਂਚ",
    story_launch_p1: "ਦੋ ਸਾਲਾਂ ਦੇ ਵਿਕਾਸ ਅਤੇ ਰੈਗੂਲੇਟਰੀ ਮਨਜ਼ੂਰੀ ਤੋਂ ਬਾਅਦ, ਅਸੀਂ ਚੁਣੇ ਹੋਏ ਨਿਵੇਸ਼ ਮੌਕਿਆਂ ਦੇ ਪਹਿਲੇ ਸੈੱਟ ਨਾਲ ਆਪਣਾ ਪਲੇਟਫਾਰਮ ਲਾਂਚ ਕੀਤਾ।",
    story_launch_p2: "ਕੁਝ ਮਹੀਨਿਆਂ ਵਿੱਚ ਹਜ਼ਾਰਾਂ ਨਿਵੇਸ਼ਕ ਸਾਡੇ ਨਾਲ ਜੁੜੇ ਅਤੇ ਲੱਖਾਂ ਦੀ ਰੀਅਲ ਅਸਟੇਟ ਨਿਵੇਸ਼ ਸੰਭਵ ਹੋਈ, ਸ਼ਰੀਆ ਪਾਲਣਾ ਦੀ ਵਚਨਬੱਧਤਾ ਕਾਇਮ ਰੱਖਦੇ ਹੋਏ।",
    story_future_title: "ਭਵਿੱਖ",
    story_future_p1: "ਅਸੀਂ ਹੁਣੇ ਸ਼ੁਰੂਆਤ ਕੀਤੀ ਹੈ। ਸਾਡੀ ਯੋਜਨਾ ਵਿੱਚ ਅੰਤਰਰਾਸ਼ਟਰੀ ਬਾਜ਼ਾਰਾਂ ਵਿੱਚ ਵਿਸਥਾਰ, ਨਵੀਆਂ ਸੰਪਤੀ ਸ਼੍ਰੇਣੀਆਂ ਜੋੜਨਾ ਅਤੇ ਇਸਲਾਮੀ ਫਿਨਟੈਕ ਵਿੱਚ ਨਵੀਨਤਾ ਜਾਰੀ ਰੱਖਣਾ ਸ਼ਾਮਲ ਹੈ।",
    about_licensed: "ਸਾਊਦੀ ਅਰਬ ਵਿੱਚ ਲਾਇਸੰਸਸ਼ੁਦਾ ਅਤੇ ਨਿਯੰਤ੍ਰਿਤ",
    story_global_label: "ਵਿਸ਼ਵ ਪੱਧਰੀ ਵਿਸਥਾਰ",
    about_cta_title: "ਸਾਡੇ ਮਿਸ਼ਨ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ",
    about_cta_sub: "ਸਾਊਦੀ ਅਰਬ ਦੇ ਰੀਅਲ ਅਸਟੇਟ ਬਦਲਾਅ ਦਾ ਹਿੱਸਾ ਬਣੋ। ਅੱਜ ਹੀ ਸਾਡੇ ਨਾਲ ਆਪਣਾ ਨਿਵੇਸ਼ ਸਫ਼ਰ ਸ਼ੁਰੂ ਕਰੋ।",
    terms_conditions: "ਨਿਯਮ ਅਤੇ ਸ਼ਰਤਾਂ",
    home_badge: "ਸ਼ਰੀਆ ਅਨੁਕੂਲ · ਵਿਜ਼ਨ 2030 ਦੇ ਅਨੁਸਾਰ",
    home_title_line1: "ਸਾਊਦੀ ਅਰਬ ਦੇ",
