    testimonial_1_quote: "ਜ਼ਾਰੋਨ ਨੇ ਮੇਰੀ ਨਿਵੇਸ਼ ਰਣਨੀਤੀ ਬਦਲ ਦਿੱਤੀ। ਪਲੇਟਫਾਰਮ ਦੀ ਪਾਰਦਰਸ਼ਤਾ ਅਤੇ ਸ਼ਰੀਆ-ਅਨੁਕੂਲ ਵਿਕਲਪ ਮੇਰੀਆਂ ਕਦਰਾਂ-ਕੀਮਤਾਂ ਨਾਲ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੇਲ ਖਾਂਦੇ ਹਨ। ਹਰ ਮਹੀਨੇ ਲਗਾਤਾਰ ਰਿਟਰਨ।",
    testimonial_2_quote: "ਰੀਅਲ ਅਸਟੇਟ ਵਿੱਚ ਘੱਟੋ-ਘੱਟ ਰਕਮ ਹਮੇਸ਼ਾ ਰੁਕਾਵਟ ਸੀ। ਜ਼ਾਰੋਨ ਨੇ ਇਹ ਪੂਰੀ ਤਰ੍ਹਾਂ ਬਦਲ ਦਿੱਤਾ — ਮੈਂ SAR 5,000 ਤੋਂ ਸ਼ੁਰੂ ਕੀਤਾ ਅਤੇ ਮਜ਼ਬੂਤ ਪੋਰਟਫੋਲੀਓ ਬਣਾਇਆ।",
