    about_story_sub: "আমরা কীভাবে শুরু করেছি এবং কোথায় যাচ্ছি।",
    story_beginning_title: "শুরু",
    story_beginning_p1: "২০২২ সালে রিয়েল এস্টেট ও ফিনটেক বিশেষজ্ঞদের একটি দল দ্বারা প্রতিষ্ঠিত, জারনের জন্ম একটি সাধারণ পর্যবেক্ষণ থেকে: সৌদি আরবের ক্রমবর্ধমান রিয়েল এস্টেট বাজার কেবল ধনী শ্রেণির জন্যই উন্মুক্ত ছিল।",
    story_beginning_p2: "আমরা এই প্রবেশাধিকার সবার জন্য উন্মুক্ত করার এবং ভিশন ২০৩০-এর অর্থনৈতিক বৈচিত্র্য ও খুচরা বিনিয়োগ অংশগ্রহণ বাড়ানোর লক্ষ্যের সাথে সংযুক্ত করার সুযোগ দেখেছি।",
    story_founded_label: "জারন প্রতিষ্ঠা",
    story_launch_title: "প্ল্যাটফর্ম চালু",
    story_launch_p1: "দুই বছরের উন্নয়ন ও নিয়ন্ত্রক অনুমোদনের পর, আমরা বাছাইকৃত বিনিয়োগ সুযোগের প্রথম সেট নিয়ে আমাদের প্ল্যাটফর্ম চালু করি।",
    story_launch_p2: "কয়েক মাসের মধ্যে হাজারো বিনিয়োগকারী যুক্ত হন এবং লক্ষ লক্ষ টাকার রিয়েল এস্টেট বিনিয়োগ সহজ হয়, শরিয়াহ সম্মতির অঙ্গীকার বজায় রেখে।",
    story_future_title: "ভবিষ্যৎ",
    story_future_p1: "আমরা কেবল শুরু করেছি। আমাদের পরিকল্পনায় রয়েছে আন্তর্জাতিক বাজারে সম্প্রসারণ, নতুন সম্পদ শ্রেণি যোগ করা এবং ইসলামী ফিনটেকে উদ্ভাবন অব্যাহত রাখা।",
