    testimonial_1_quote: "জারন আমার বিনিয়োগ কৌশল বদলে দিয়েছে। প্ল্যাটফর্মের স্বচ্ছতা ও শরিয়াহ-সম্মত বিকল্প আমার মূল্যবোধের সাথে পুরোপুরি মেলে। প্রতি মাসে ধারাবাহিক রিটার্ন।",
    testimonial_2_quote: "রিয়েল এস্টেটে ন্যূনতম বিনিয়োগ সবসময় বাধা ছিল। জারন তা সম্পূর্ণ বদলে দিয়েছে — আমি SAR ৫,০০০ দিয়ে শুরু করে ধারাবাহিকভাবে শক্ত পোর্টফোলিও গড়েছি।",
    testimonial_3_quote: "প্ল্যাটফর্মটি অবিশ্বাস্যভাবে সহজবোধ্য। আমি আমার পুরো পোর্টফোলিও এক জায়গায় ট্র্যাক করি এবং মাসিক রিটার্ন নিয়মিত আমার ওয়ালেটে আসে। অত্যন্ত সুপারিশকৃত।",
