    about_team_sub: "സൗദി അറേബ്യയിലെ റിയൽ എസ്റ്റേറ്റ് നിക്ഷേപം പരിവർത്തനം ചെയ്യാൻ സമർപ്പിതരായ പരിചയസമ്പന്നരായ വിദഗ്ധർ.",
