    about_story_sub: "ഞങ്ങൾ എങ്ങനെ തുടങ്ങി, എങ്ങോട്ട് പോകുന്നു.",
    story_beginning_title: "തുടക്കം",
    story_beginning_p1: "2022-ൽ റിയൽ എസ്റ്റേറ്റ്, ഫിൻടെക് വിദഗ്ധരുടെ ഒരു സംഘം സ്ഥാപിച്ച സാരോൺ ഒരു ലളിതമായ നിരീക്ഷണത്തിൽ നിന്നാണ് പിറന്നത്: സൗദി അറേബ്യയുടെ വളരുന്ന റിയൽ എസ്റ്റേറ്റ് വിപണി സമ്പന്നർക്ക് മാത്രമേ പ്രാപ്യമായിരുന്നുള്ളൂ.",
    story_beginning_p2: "ഈ പ്രവേശനം ജനാധിപത്യവൽക്കരിക്കാനും വിഷൻ 2030-ന്റെ സാമ്പത്തിക വൈവിധ്യവൽക്കരണ, റീട്ടെയിൽ നിക്ഷേപ പങ്കാളിത്ത ലക്ഷ്യങ്ങളുമായി യോജിപ്പിക്കാനുമുള്ള അവസരം ഞങ്ങൾ കണ്ടു.",
    story_founded_label: "സാരോൺ സ്ഥാപിതമായി",
    story_launch_title: "പ്ലാറ്റ്‌ഫോം ലോഞ്ച്",
    story_launch_p1: "രണ്ട് വർഷത്തെ വികസനത്തിനും നിയന്ത്രണ അനുമതിക്കും ശേഷം, തിരഞ്ഞെടുത്ത നിക്ഷേപ അവസരങ്ങളുടെ ആദ്യ സെറ്റുമായി ഞങ്ങൾ പ്ലാറ്റ്‌ഫോം ആരംഭിച്ചു.",
    story_launch_p2: "മാസങ്ങൾക്കുള്ളിൽ ആയിരക്കണക്കിന് നിക്ഷേപകർ ചേർന്നു, ദശലക്ഷക്കണക്കിന് റിയൽ എസ്റ്റേറ്റ് നിക്ഷേപം സാധ്യമാക്കി — ശരിയ അനുസൃതിയോടുള്ള പ്രതിബദ്ധത നിലനിർത്തിക്കൊണ്ട്.",
    story_future_title: "ഭാവി",
    story_future_p1: "ഞങ്ങൾ ഇപ്പോൾ തുടങ്ങിയതേയുള്ളൂ. അന്താരാഷ്ട്ര വിപണികളിലേക്കുള്ള വ്യാപനം, പുതിയ ആസ്തി വിഭാഗങ്ങൾ ചേർക്കൽ, ഇസ്ലാമിക് ഫിൻടെക്കിലെ നൂതനത്വം തുടരൽ എന്നിവ ഞങ്ങളുടെ പദ്ധതിയിലുണ്ട്.",
    about_licensed: "സൗദി അറേബ്യയിൽ ലൈസൻസുള്ളതും നിയന്ത്രിതവും",
    story_global_label: "ആഗോള വ്യാപനം",
